"use client";
import { useCheckout, errorMessage } from '@paykit/react';
export function CustomCheckout({ sessionId, amount, className, onPaid }: {
  sessionId: string; amount: string; className?: string; onPaid?: (paymentId: string) => void;
}) {
  const checkout = useCheckout();
  return <div className={className}>
    <button disabled={checkout.busy} onClick={() => {
      checkout.pay({ sessionId }, { expectedAmount: amount }).then((payment) => onPaid?.(payment.paymentId)).catch(() => {});
    }}>{checkout.busy ? 'Processing payment…' : 'Pay with USDT'}</button>
    {checkout.error != null && <p role="alert">{errorMessage(checkout.error)}</p>}
    {checkout.payment && <p aria-live="polite">{checkout.payment.status}</p>}
  </div>;
}

"use client";
import { usePayment, errorMessage } from '@paykit/react';
export function CustomPaymentStatus({ paymentId, className }: { paymentId: string; className?: string }) {
  const { data, loading, error, refetch } = usePayment(paymentId);
  return <div className={className} aria-live="polite">
    {error != null ? <><p role="alert">{errorMessage(error)}</p><button onClick={refetch}>Try again</button></>
      : !data ? <p>{loading ? 'Checking payment…' : 'Payment unavailable'}</p>
      : <><p>Payment {data.status}</p>{data.explorerUrl && <a href={data.explorerUrl} target="_blank" rel="noreferrer">View transaction</a>}</>}
  </div>;
}
